// controlPlaneClusterDiscoveryTimeout bounds the one
// /.well-known/entire-cluster.json GET a cluster-addressed control-plane
// command makes to learn which core fronts the cluster. Short so an absent or
// slow endpoint fails the command promptly.
const controlPlaneClusterDiscoveryTimeout = 8 * time.Second

// resolveContextForCluster is the discovery seam, swapped in tests so they
// don't reach the network. Mirrors clusterdiscovery.ResolveContextForCluster.
var resolveContextForCluster resolveContextFunc = clusterdiscovery.ResolveContextForCluster

// ControlPlaneTarget is the resolved login server a control-plane request
// (org/repo/project/grant) should dial, plus the bearer source for it.
//
// CoreURL is an origin (no /api/v1 suffix); the caller appends the API base
// path. TokenSource returns a bearer valid for CoreURL, re-minting silently
// from the stored refresh token when the active context drives resolution.
type ControlPlaneTarget struct {
	CoreURL     string
	TokenSource func(context.Context) (string, error)
}

// ResolveControlPlaneTarget chooses which core the control-plane commands talk
// to and how their bearer is obtained. The control-plane host *is* a core, so
// there is no /.well-known discovery here — the active context names the core,
// which is what makes `entire auth use <ctx>` retarget the control plane onto
// that login server. The bearer is a per-context refreshing provider (silent
// JWT re-mint from the stored refresh token).
//
// No active context means not logged in: the error wraps ErrNotLoggedIn so
// callers render the `entire login` hint. There is no fallback host — a
// control-plane command without a login has no identity to act as.
func ResolveControlPlaneTarget() (ControlPlaneTarget, error) {
	c, ok, err := activeContext()
	if err != nil {
		return ControlPlaneTarget{}, err
	}
	if !ok {
		return ControlPlaneTarget{}, &reauthError{
			msg:      "not logged in; run `entire login`",
			sentinel: ErrNotLoggedIn,
		}
	}

	return targetForContext(c)
}

// ResolveControlPlaneTargetForCluster chooses which core a *resource-provider*
// control-plane command should dial — one whose subject is a mirror on a
// specific cluster (mirror create/remove, mirror collaborators list)
// rather than the caller's own account.
//
// Unlike ResolveControlPlaneTarget, the core is NOT taken from the active
// context: a cluster's mirror lives in the federation that fronts that cluster,
// which may differ from the active login (e.g. a partial.to context acting on a
// prod entire.io cluster). We discover the cluster's trusted cores from its
// /.well-known/entire-cluster.json and pick the local context eligible for one
// of them — active-wins-if-eligible, else the sole eligible context, else an
// explicit-choice / login hint — exactly as git and data-API resolution do
// (see ResolveDataAPIToken). The bearer is that context's
// refreshing login provider (silent JWT re-mint from its stored refresh token).
//
// With no eligible local context the discovery resolver returns its login hint
// naming the cluster's cores, so the user logs in to the right federation
// rather than seeing an opaque "unknown cluster_host" 400 from the active
// context's core.
func ResolveControlPlaneTargetForCluster(ctx context.Context, clusterHost string) (ControlPlaneTarget, error) {
	if clusterHost == "" {
		return ControlPlaneTarget{}, errors.New("cluster-addressed control-plane command requires a target cluster host")
	}
	httpClient := &http.Client{Timeout: controlPlaneClusterDiscoveryTimeout}
	c, err := resolveContextForCluster(ctx, userdirs.Config(), userdirs.Cache(), clusterHost, httpClient, nil)
	if err != nil {
		return ControlPlaneTarget{}, err
	}
	return targetForContext(c)
}

// targetForContext builds the ControlPlaneTarget for an already-chosen context:
// a refreshing login provider (silent JWT re-mint from the stored refresh
// token) bound to that context's core. Shared by the active-context and
// cluster-addressed resolvers, which differ only in how they pick c.
func targetForContext(c *contexts.Context) (ControlPlaneTarget, error) {
	src, err := NewRefreshingLoginProvider(c, nil, insecureHTTPEnabled() || isLoopbackHTTP(c.CoreURL))
	if err != nil {
		return ControlPlaneTarget{}, fmt.Errorf("build token source for context %q: %w", c.Name, err)
	}
	return ControlPlaneTarget{CoreURL: strings.TrimRight(c.CoreURL, "/"), TokenSource: src}, nil
}

// activeContext returns the active contexts.json login and ok=true, or
// ok=false when there is no current context or it carries no CoreURL (an
// unusable pointer we treat as "no active context" rather than dialing an
// empty host).
func activeContext() (c *contexts.Context, ok bool, err error) {
	f, err := contexts.Load(userdirs.Config())
	if err != nil {
		return nil, false, fmt.Errorf("load contexts: %w", err)
	}
	c = f.Find(f.CurrentContext)
	if c == nil || c.CoreURL == "" {
		return nil, false, nil
	}
	return c, true, nil
}

package clusterdiscovery

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"strings"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/discovery"
)

// ResolveContextForCluster picks the local login context to authenticate
// git operations against clusterHost.
//
// It separates two concerns that used to be conflated in a single
// cluster→context binding:
//
//   - Which control plane(s) front the cluster — an objective infra fact.
//     Discovered from the cluster's /.well-known/entire-cluster.json and
//     cached in cluster_cores.json (see discovery.ClusterCoresCache) with
//     a long TTL, since a cluster's home core is near-static. On a cache
//     miss or expiry we re-fetch; if the re-fetch fails we fall back to
//     the stale cached cores rather than break the op.
//
//   - Which of the user's accounts to use — recomputed every call from the
//     live contexts, never persisted. So a user with several accounts is
//     never silently pinned to one identity.
//
// Account selection (selectContext):
//
//  1. If the active context (current_context) is issued by one of the
//     cluster's cores, use it. This is the explicit lever: `entire auth
//     use <name>` chooses the identity for every cluster that context's
//     core fronts.
//  2. Otherwise gather every local context eligible for the cluster (its
//     CoreURL is among the advertised cores):
//     - exactly one  → use it (the common single-account case);
//     - none         → error with the login hint listing the cluster's cores;
//     - more than one → error asking the user to pick with `entire auth use`,
//     rather than silently guessing an account.
//
// We never fall back to an active context whose core does NOT front the
// cluster: the cluster would reject the exchanged token as "unknown
// cluster_host", and silently authenticating a staging identity against a
// prod cluster (or vice versa) is exactly the confusion the /.well-known
// lookup exists to prevent.
//
// debugf is optional; nil suppresses debug output.
func ResolveContextForCluster(ctx context.Context, configDir, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) (*contexts.Context, error) {
	a, err := resolveClusterAuth(ctx, configDir, cacheDir, clusterHost, false, httpClient, debugf)
	if err != nil {
		return nil, err
	}
	return a.Context, nil
}

// ClusterAuth is ResolveClusterAuth's result: the selected login context
// plus the cluster facts a caller needs to mint credentials for it.
type ClusterAuth struct {
	Context *contexts.Context
	// JurisdictionAudience is the cluster's jurisdiction-token audience; empty
	// when the cluster doesn't advertise one.
	JurisdictionAudience string
	// JurisdictionCoreURL is the advertised core minting for that audience —
	// the cross-jurisdiction exchange endpoint.
	JurisdictionCoreURL string
}

// ResolveClusterAuth is ResolveContextForCluster plus the cluster's
// advertised jurisdiction metadata, sharing the same cache and single
// /.well-known fetch. Because its callers cannot proceed without the
// jurisdiction audience, resolution requires one (see resolveCachedCores).
func ResolveClusterAuth(ctx context.Context, configDir, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) (*ClusterAuth, error) {
	return resolveClusterAuth(ctx, configDir, cacheDir, clusterHost, true, httpClient, debugf)
}

// resolveClusterAuth is the shared body of ResolveContextForCluster and
// ResolveClusterAuth: load contexts, resolve the cluster's cores entry,
// select the login context.
func resolveClusterAuth(ctx context.Context, configDir, cacheDir, clusterHost string, requireAudience bool, httpClient *http.Client, debugf DebugFunc) (*ClusterAuth, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	// DNS hostnames are case-insensitive, so fold case before the host drives any
	// lookup: the cache key, the /.well-known fetch, and the cores→context match.
	// Without this, `aws-US-east-2.entire.io` and `aws-us-east-2.entire.io`
	// resolve as different hosts and a context determination can fail spuriously.
	clusterHost = normalizeClusterHost(clusterHost)
	f, err := contexts.Load(configDir)
	if err != nil {
		return nil, fmt.Errorf("load contexts: %w", err)
	}

	entry, err := resolveClusterCores(ctx, cacheDir, clusterHost, requireAudience, httpClient, debugf)
	if err != nil {
		return nil, err
	}

	selected, err := selectContext(f, "cluster "+clusterHost, entry.CoreURLs, debugf)
	if err != nil {
		return nil, err
	}
	return &ClusterAuth{
		Context:              selected,
		JurisdictionAudience: entry.JurisdictionAudience,
		JurisdictionCoreURL:  entry.JurisdictionCoreURL,
	}, nil
}

// ResolveClusterCores returns the cluster's discovery entry — the trusted
// control-plane core URLs that front clusterHost plus its advertised
// jurisdiction audience/core — using the same cache-then-/.well-known
// discovery as ResolveContextForCluster (see resolveClusterCores). Exported
// for callers that need the cluster facts without account selection — e.g.
// the ENTIRE_TOKEN path validates that the env token's audience is one of
// the advertised cores before exchanging it, so an unverified JWT can't
// redirect the token exchange to an attacker-chosen host. Its sole caller
// mints jurisdiction tokens, so the audience-requiring cache semantics
// apply (see resolveCachedCores).
func ResolveClusterCores(ctx context.Context, cacheDir, clusterHost string, httpClient *http.Client, debugf DebugFunc) (*discovery.CoresEntry, error) {
	if debugf == nil {
		debugf = func(string, ...any) {}
	}
	return resolveClusterCores(ctx, cacheDir, normalizeClusterHost(clusterHost), true, httpClient, debugf)
}

// normalizeClusterHost folds a cluster host to its canonical form for use as a
// lookup key. DNS is case-insensitive, so two hosts differing only in case (or
// surrounding whitespace) name the same cluster and must resolve identically —
// for the host→cores cache, /.well-known discovery, and context determination.
func normalizeClusterHost(clusterHost string) string {
	return strings.ToLower(strings.TrimSpace(clusterHost))
}

// resolveCachedCores is the shared cache-then-/.well-known resolution behind
// both resolveClusterCores (git clusters) and resolveAPICores (data APIs):
// read the host→cores cache, return it when fresh, otherwise discover live and
// rewrite the cache. A stale-but-present entry is used as a fallback when the
// live fetch fails, so a brief outage doesn't break a host whose cores we
// already knew. load/modify select the cache file; discover wraps the
// host-specific /.well-known fetch (and any host-specific error formatting);
// label names the resource in debug output ("cluster" / "api host").
//
// requireAudience marks callers that cannot proceed without the entry's
// jurisdiction audience (both git auth paths). For them, an entry
// cached before the cluster advertised an audience is treated as stale so
// the upgrade is picked up immediately instead of after the 24h TTL — and
// an audience-less entry is NOT used as the discovery-failure fallback:
// returning it would make the caller misdiagnose a transient discovery
// failure as "this cluster doesn't do jurisdiction tokens".
func resolveCachedCores(
	cacheDir, host, label string,
	requireAudience bool,
	load func(string) (discovery.ClusterCoresCache, error),
	modify func(string, func(discovery.ClusterCoresCache) error) error,
	discover func() (discovery.CoresEntry, error),
	debugf DebugFunc,
) (*discovery.CoresEntry, error) {
	cache, err := load(cacheDir)
	if err != nil {
		// A cache read problem must not block resolution — discover live.
		debugf("%s cache load failed: %v; discovering live", label, err)
		cache = nil
	}

	var stale *discovery.CoresEntry
	if cache != nil {
		if entry, fresh, ok := cache.GetEntry(host); ok {
			preAudience := requireAudience && entry.JurisdictionAudience == ""
			if fresh && !preAudience {
				debugf("%s %s cores from cache: %v", label, host, entry.CoreURLs)
				return entry, nil
			}
			stale = entry
			debugf("%s %s cores cache expired or pre-audience; re-fetching /.well-known", label, host)
		}
	}

	fetched, err := discover()
	if err != nil {
		if stale != nil && (!requireAudience || stale.JurisdictionAudience != "") {
			debugf("%s discovery for %s failed (%v); falling back to stale cached cores %v", label, host, err, stale.CoreURLs)
			return stale, nil
		}
		return nil, err
	}

	if mErr := modify(cacheDir, func(c discovery.ClusterCoresCache) error {
		c.SetEntry(host, fetched)
		return nil
	}); mErr != nil {
		// Non-fatal: we resolved the cores, the next call just re-fetches.
		debugf("%s cache write for %s failed: %v", label, host, mErr)
	}
	return &fetched, nil
}

// resolveClusterCores returns the control-plane core URLs that front
// clusterHost plus its advertised jurisdiction audience/core, from
// cluster_cores.json when fresh, otherwise via a live /.well-known fetch
// (cached, with stale fallback on failure). requireAudience: see
// resolveCachedCores.
func resolveClusterCores(ctx context.Context, cacheDir, clusterHost string, requireAudience bool, httpClient *http.Client, debugf DebugFunc) (*discovery.CoresEntry, error) {
	return resolveCachedCores(cacheDir, clusterHost, "cluster", requireAudience,
		discovery.LoadClusterCores, discovery.ModifyClusterCores,
		func() (discovery.CoresEntry, error) {
			body, err := Discover(ctx, clusterHost, httpClient, debugf)
			if err != nil {
				return discovery.CoresEntry{}, formatDiscoveryError(clusterHost, err)
			}
			return discovery.CoresEntry{
				CoreURLs:             body.CoreURLs,
				JurisdictionAudience: body.JurisdictionAudience,
				JurisdictionCoreURL:  body.JurisdictionCoreURL,
			}, nil
		}, debugf)
}

// selectContext applies the account-selection rules over a resource's
// advertised trusted issuers. subject is a noun phrase identifying the
// resource ("cluster nyc.entire.io" / "API host partial.to") used in
// messages, so the same rules serve both the git-cluster and data-API
// resolvers. See ResolveContextForCluster for the rationale.
func selectContext(f *contexts.File, subject string, coreURLs []string, debugf DebugFunc) (*contexts.Context, error) {
	eligible := eligibleContexts(f, coreURLs)

	// 1. Active context wins when it's eligible for this resource.
	if current := f.Find(f.CurrentContext); current != nil {
		for _, c := range eligible {
			if c.Name == current.Name {
				debugf("%s -> active context %s", subject, current.Name)
				return current, nil
			}
		}
	}

	// 2. Otherwise the eligible set decides.
	switch len(eligible) {
	case 0:
		return nil, errors.New(renderLoginHint(subject, coreURLs))
	case 1:
		debugf("%s -> sole eligible context %s", subject, eligible[0].Name)
		return eligible[0], nil
	default:
		return nil, ambiguousContextError(subject, eligible)
	}
}

// eligibleContexts returns the local contexts whose core is among coreURLs,
// de-duplicated by name. Order is unspecified — callers either use the sole
// element or report the whole set, never index [0] as a silent winner.
func eligibleContexts(f *contexts.File, coreURLs []string) []*contexts.Context {
	seen := make(map[string]bool)
	var out []*contexts.Context
	for _, coreURL := range coreURLs {
		for _, c := range f.ContextsForIssuer(coreURL) {
			if !seen[c.Name] {
				seen[c.Name] = true
				out = append(out, c)
			}
		}
	}
	return out
}

// ambiguousContextError is returned when more than one local context could
// authenticate against the resource and none is active. We refuse to guess —
// the user picks explicitly. Names are sorted so the message is stable.
func ambiguousContextError(subject string, eligible []*contexts.Context) error {
	names := make([]string, len(eligible))
	for i, c := range eligible {
		names[i] = c.Name
	}
	sort.Strings(names)
	return fmt.Errorf("multiple login contexts can authenticate against %s (%s); choose one with `entire auth use <context>` and re-run",
		subject, strings.Join(names, ", "))
}

// formatDiscoveryError turns a Discover error into the message
// operators have always seen at this layer. Kept here (not on the
// sentinels themselves) so the package's errors stay machine-readable
// while the caller-facing strings remain centralised.
func formatDiscoveryError(clusterHost string, err error) error {
	switch {
	case errors.Is(err, ErrUnreachable):
		return fmt.Errorf("%s doesn't look like a cluster, or it is unreachable: %w", clusterHost, err)
	case errors.Is(err, ErrNoIssuers):
		return fmt.Errorf("cluster %s does not advertise any trusted login servers (HTTP 503 from %s); contact the cluster administrator",
			clusterHost, Path)
	case errors.Is(err, ErrNoCoreURLs):
		return fmt.Errorf("cluster %s advertises no trusted core URLs (empty list at %s); contact the cluster administrator",
			clusterHost, Path)
	default:
		return fmt.Errorf("cluster discovery for %s: %w", clusterHost, err)
	}
}

package auth

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/auth-go/tokenmanager"
	"github.com/entireio/auth-go/tokens"
	authtokenstore "github.com/entireio/auth-go/tokenstore"

	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/tokenstore"
)

// defaultSavedTokenTTL is the encoded keychain expiry used when a refreshed
// token carries no usable ExpiresAt. The server is the real authority; this
// only governs when local readers consider the cached token stale.
const defaultSavedTokenTTL = time.Hour

// contextTokenStore adapts one login context's keyring slots to auth-go's
// tokenstore.Store, so tokenmanager can load, refresh, and persist that
// context's credentials. It is bound to a specific (service, handle) at
// construction and ignores the profile argument: the cluster resolver has
// already chosen exactly one context, so there is no per-issuer account
// ambiguity to resolve here.
//
// Access token lives at `service`/`handle` (with the "|<expiry>" encoding
// the rest of the CLI reads); the refresh token lives raw at
// `service:refresh`/`handle`.
type contextTokenStore struct {
	service string
	handle  string
}

func (s contextTokenStore) LoadTokens(string) (tokens.TokenSet, error) {
	enc, err := tokenstore.Get(s.service, s.handle)
	// Map "no credential stored" to auth-go's sentinel so tokenmanager
	// reports "not logged in" rather than a hard store failure.
	if errors.Is(err, tokenstore.ErrNotFound) || (err == nil && enc == "") {
		return tokens.TokenSet{}, authtokenstore.ErrNotFound
	}
	if err != nil {
		return tokens.TokenSet{}, fmt.Errorf("read access token: %w", err)
	}
	access, expiresAt := tokenstore.DecodeTokenWithExpiration(enc)
	// A missing refresh slot is fine (login predating offline_access) — treat
	// it as no-refresh. Any other store error must surface, not be swallowed:
	// dropping it would silently discard a valid refresh token and force a
	// re-login on what was really a transient keyring/file-store failure.
	refresh, err := tokenstore.Get(tokenstore.RefreshService(s.service), s.handle)
	if err != nil && !errors.Is(err, tokenstore.ErrNotFound) {
		return tokens.TokenSet{}, fmt.Errorf("read refresh token: %w", err)
	}
	return tokens.TokenSet{
		AccessToken:  access,
		RefreshToken: refresh,
		ExpiresAt:    expiresAt,
	}, nil
}

func (s contextTokenStore) SaveTokens(_ string, t tokens.TokenSet) error {
	if t.AccessToken == "" {
		return errors.New("save tokens: empty access token")
	}
	expiresIn := int64(defaultSavedTokenTTL.Seconds())
	if !t.ExpiresAt.IsZero() {
		if secs := int64(time.Until(t.ExpiresAt).Seconds()); secs > 0 {
			expiresIn = secs
		}
	}
	// Persist the rotated refresh token BEFORE the access token. The server
	// single-use-rotates refresh tokens, so a partial write must never leave
	// a fresh access token paired with a stale refresh token: that pairing
	// looks healthy until the access token expires, then the dead refresh
	// token trips invalid_grant/family revocation and forces a re-login.
	// Refresh-first inverts the failure modes: a failed refresh write aborts
	// before touching the access slot (old pair preserved), and a failed
	// access write after a good refresh write self-heals on the next load
	// (the new refresh token re-mints an access token).
	//
	// persistRefreshed carries a still-valid refresh token forward when the
	// server doesn't rotate, so an empty value here means "leave as-is",
	// never "clear".
	if t.RefreshToken != "" {
		if err := tokenstore.Set(tokenstore.RefreshService(s.service), s.handle, t.RefreshToken); err != nil {
			return fmt.Errorf("store refresh token: %w", err)
		}
	}
	if err := tokenstore.Set(s.service, s.handle, tokenstore.EncodeTokenWithExpiration(t.AccessToken, expiresIn)); err != nil {
		return fmt.Errorf("store access token: %w", err)
	}
	return nil
}

func (s contextTokenStore) DeleteTokens(string) error {
	_ = tokenstore.Delete(tokenstore.RefreshService(s.service), s.handle) //nolint:errcheck // best-effort; the access-token delete below is what matters
	if err := tokenstore.Delete(s.service, s.handle); err != nil {
		return fmt.Errorf("delete access token: %w", err)
	}
	return nil
}

// newContextTokenManager builds the per-context auth-go tokenmanager that both
// NewRefreshingLoginProvider and NewRefreshingResourceProvider sit on. Keying
// Issuer on c.CoreURL is the whole point: store reads, the refresh grant, and
// the STS exchange all target that context's core, so a multi-core user's
// credentials never travel to (or get keyed under) a host the context
// doesn't belong to.
//
// transport carries the caller's TLS configuration; allowInsecureHTTP permits
// an http:// core/resource for loopback/dev.
func newContextTokenManager(c *contexts.Context, transport http.RoundTripper, allowInsecureHTTP bool) (*tokenmanager.Manager, error) {
	if c == nil {
		return nil, errors.New("nil context")
	}
	if c.KeychainService == "" || c.Handle == "" {
		return nil, fmt.Errorf("context %q has no keychain slot", c.Name)
	}
	mgr, err := tokenmanager.New(tokenmanager.Config{
		Issuer:            strings.TrimRight(c.CoreURL, "/"),
		ClientID:          oauthClientID,
		STSPath:           oauthSTSPath,
		RefreshPath:       oauthTokenPath,
		Store:             contextTokenStore{service: c.KeychainService, handle: c.Handle},
		Transport:         transport,
		AllowInsecureHTTP: allowInsecureHTTP,
		UserAgent:         oauthClientID,
	})
	if err != nil {
		return nil, fmt.Errorf("init token manager for context %q: %w", c.Name, err)
	}
	return mgr, nil
}

// reauthError carries a friendly, context-named re-login message while still
// unwrapping to the underlying tokenmanager sentinel, so callers that branch
// on errors.Is(err, ErrNotLoggedIn) (NewAuthenticatedAPIClient, search,
// dispatch) keep matching. Error() returns only msg so the sentinel's terse
// text ("not logged in") doesn't leak into the rendered message.
type reauthError struct {
	msg      string
	sentinel error
}

func (e *reauthError) Error() string { return e.msg }
func (e *reauthError) Unwrap() error { return e.sentinel }

// contextReauthError maps the two re-auth sentinels a per-context manager can
// return into a friendly message that names the context and its core (so a
// multi-core user logs back into the right one — matching the
// "no auth context, run `entire login`" hint style used by clusterdiscovery),
// preserving the sentinel for errors.Is. Returns nil when err is neither
// sentinel, leaving the caller to wrap the residual error in its own terms
// (refresh vs exchange).
func contextReauthError(c *contexts.Context, err error) error {
	coreURL := strings.TrimRight(c.CoreURL, "/")
	switch {
	case errors.Is(err, tokenmanager.ErrReauthRequired):
		return &reauthError{
			msg:      fmt.Sprintf("login session for %q (%s) expired; run `entire login` to re-authenticate", c.Name, coreURL),
			sentinel: tokenmanager.ErrReauthRequired,
		}
	case errors.Is(err, tokenmanager.ErrNotLoggedIn):
		return &reauthError{
			msg:      fmt.Sprintf("no usable login for %q (%s); run `entire login`", c.Name, coreURL),
			sentinel: tokenmanager.ErrNotLoggedIn,
		}
	}
	return nil
}

// RefreshingLoginCredential resolves a context's login JWT and can force a
// refresh after a server rejects a still-locally-valid token.
type RefreshingLoginCredential struct {
	context *contexts.Context
	manager *tokenmanager.Manager
}

// NewRefreshingLoginCredential returns a refreshable login credential for
// context c.
func NewRefreshingLoginCredential(c *contexts.Context, transport http.RoundTripper, allowInsecureHTTP bool) (*RefreshingLoginCredential, error) {
	mgr, err := newContextTokenManager(c, transport, allowInsecureHTTP)
	if err != nil {
		return nil, err
	}
	return &RefreshingLoginCredential{context: c, manager: mgr}, nil
}

// Token returns a locally fresh login JWT, refreshing it when needed.
func (c *RefreshingLoginCredential) Token(ctx context.Context) (string, error) {
	tok, err := c.manager.Refresh(ctx)
	return c.result(tok, err)
}

// ForceRefresh re-mints the login JWT after staleToken was rejected by the
// server despite still appearing locally valid.
func (c *RefreshingLoginCredential) ForceRefresh(ctx context.Context, staleToken string) (string, error) {
	tok, err := c.manager.ForceRefresh(ctx, staleToken)
	return c.result(tok, err)
}

func (c *RefreshingLoginCredential) result(tok string, err error) (string, error) {
	if mapped := contextReauthError(c.context, err); mapped != nil {
		return "", mapped
	}
	if err != nil {
		return "", fmt.Errorf("refresh login token: %w", err)
	}
	return tok, nil
}

// NewRefreshingLoginProvider returns a login-JWT provider (the shape
// repocreds wants) for context c that transparently re-mints an expired login
// JWT from the stored refresh token. Call NewRefreshingLoginCredential when a
// reactive 401 path also needs to force-refresh a rejected token.
//
// It is backed by auth-go's tokenmanager, which is what makes this safe
// against the server's single-use refresh-token rotation: refreshes are
// serialised across processes (an advisory file lock) and goroutines, the
// store is re-read after locking so a late waiter reuses a peer's freshly
// minted token, and the rotated refresh token is persisted. Without that,
// two concurrent git-remote-entire processes (e.g. a recursive submodule
// fetch) could replay the same single-use token and trip the server's
// reuse detection, revoking the whole family.
//
// A still-valid token is returned with no network call. A context with no
// stored refresh token degrades gracefully: valid token used, expired token
// surfaces a re-login error.
//
// transport carries the caller's TLS configuration; allowInsecureHTTP
// permits an http:// core for loopback/dev.
func NewRefreshingLoginProvider(c *contexts.Context, transport http.RoundTripper, allowInsecureHTTP bool) (func(context.Context) (string, error), error) {
	credential, err := NewRefreshingLoginCredential(c, transport, allowInsecureHTTP)
	if err != nil {
		return nil, err
	}
	return credential.Token, nil
}

// RefreshedLoginToken returns context c's login JWT, transparently re-minting
// an expired one from the stored refresh token. It is the convenience form of
// NewRefreshingLoginProvider for callers that want a single token now (e.g.
// `auth status` / `logout`, which must report a refreshable session as alive
// rather than telling the user to re-login). The insecure-HTTP decision mirrors
// the control-plane resolver: loopback cores and the --insecure-http-auth
// opt-in are permitted, everything else requires https.
//
// Errors preserve the tokenmanager sentinels (ErrReauthRequired when the
// session is genuinely dead, ErrNotLoggedIn when no credential is usable) so
// callers can branch on errors.Is.
func RefreshedLoginToken(ctx context.Context, c *contexts.Context) (string, error) {
	if c == nil {
		return "", errors.New("nil context")
	}
	provider, err := NewRefreshingLoginProvider(c, nil, insecureHTTPEnabled() || isLoopbackHTTP(c.CoreURL))
	if err != nil {
		return "", err
	}
	return provider(ctx)
}

// NewRefreshingResourceProvider returns a provider that mints a bearer valid
// for resourceOrigin, by exchanging context c's login JWT at c's own core (RFC
// 8693). It is NewRefreshingLoginProvider's sibling for resource servers: where
// that returns the bare login JWT (the control plane / cluster cases, where the
// host is the core), this performs the token exchange the data API requires.
//
// Both the silent login-JWT re-mint and the exchange run through the shared
// per-context tokenmanager (newContextTokenManager). resourceOrigin must
// already be origin-only (no path). No audience is passed: the token manager
// defaults the RFC 8693 audience to the resource origin, which is exactly what
// the data API requires (aud == its base URI), so the audience is derived from
// the host being dialed rather than read from discovery. Exchanged tokens are
// cached in-process by the tokenmanager for the life of this process.
//
// transport carries the caller's TLS configuration; allowInsecureHTTP permits
// an http:// core/resource for loopback/dev.
func NewRefreshingResourceProvider(c *contexts.Context, resourceOrigin string, transport http.RoundTripper, allowInsecureHTTP bool) (func(context.Context) (string, error), error) {
	mgr, err := newContextTokenManager(c, transport, allowInsecureHTTP)
	if err != nil {
		return nil, err
	}
	req := tokenmanager.TokenRequest{Resource: resourceOrigin}
	return func(ctx context.Context) (string, error) {
		tok, err := mgr.Token(ctx, req)
		if mapped := contextReauthError(c, err); mapped != nil {
			return "", mapped
		}
		if err != nil {
			return "", fmt.Errorf("exchange token for %s: %w", resourceOrigin, err)
		}
		return tok, nil
	}, nil
}

