	stored := makeContextJWT(t, fmt.Sprintf(`{"iss":"`+testCoreURL+`","handle":"alice","exp":%d}`, exp))
	if _, err := auth.RecordLoginContext(stored, "", true); err != nil {
		t.Fatalf("record context: %v", err)
	}

